html:
{#-
  Print Format : Vking Facture
  DocType      : Sales Invoice   |  Type: Jinja  |  Standard: No  |  Custom Format: Yes
  Purpose      : Page 1 only (invoice). The Swiss QR slip is added by the
                 swiss_accounting_software app ({invoice}-QR.pdf) - do NOT add a QR here.
  Ported from the client's ERPNext v14 template, with the faulty QR section removed.
-#}

{%- macro chf(v) -%}{{ "{:,.2f}".format((v or 0)|float).replace(",", "'") }}{%- endmacro -%}

{%- macro items_header(show_discount) -%}
<tr>
	<th style="width: {{ '51%' if show_discount else '58%' }};">{{ _("Description") }}</th>
	<th style="width: 7%;">{{ _("UoM") }}</th>
	<th style="width: 5%;" class="text-right">{{ _("Qty") }}</th>
	<th style="width: 15%;" class="text-right">{{ _("Rate") }}</th>
	{% if show_discount %}<th style="width: 7%;" class="text-right">{{ _("Discount") }}</th>{% endif %}
	<th style="width: 15%;" class="text-right">{{ _("Amount") }}</th>
</tr>
{%- endmacro -%}

{%- set show_discount = doc.get("print_discount_per_item") -%}
{%- if doc.rounded_total -%}
	{%- set total_due = doc.rounded_total -%}
{%- else -%}
	{%- set total_due = (((doc.grand_total or 0)|float * 20)|round) / 20 -%}
{%- endif -%}

<style>
	.vk { font-size: 10pt; color: #000; }
	.vk table.layout { width: 100%; border-collapse: collapse; }
	.vk table.layout td { vertical-align: top; padding: 0; border: none !important; }
	.vk .line { margin-bottom: 4px; }
	.vk table.items { width: 100%; border-collapse: collapse; margin-top: 20px; }
	.vk table.items th { border: 1px solid #d1d8dd; padding: 5px; font-weight: bold; }
	.vk table.items td { border-bottom: 1px solid #ebeff2; padding: 5px; vertical-align: top; }
	.vk table.totals { width: 45%; margin-left: 55%; border-collapse: collapse; margin-top: 15px; }
	.vk table.totals td { padding: 3px 5px; border: none !important; }
	.vk .grand td { font-weight: bold; font-size: 11pt; padding-top: 10px; }
	.vk .terms { margin-top: 25px; }
	.vk .text-right { text-align: right; }
</style>

<div class="vk">

	{# Letter head (uses the letter head chosen in the print dialog / default letter head) #}
	{% if letter_head and not no_letterhead %}
	<div class="letter-head">{{ letter_head }}</div>
	{% endif %}

	{%- if doc.docstatus == 2 -%}
	<div class="text-center"><h4 style="margin: 0;">{{ _("CANCELLED") }}</h4></div>
	{%- endif -%}

	<table class="layout" style="margin-top: 20px;">
		<tr>
			<td style="width: 68%;">
				<div class="line"><strong>{{ _("Facture N° :") }}</strong>&ensp;{{ doc.get("sub_heading") or doc.name }}</div>
				<div class="line"><strong>{{ _("Du :") }}</strong>&ensp;{{ doc.get_formatted("posting_date") }}</div>
			</td>
			<td style="width: 32%;"></td>
		</tr>
		<tr>
			<td style="width: 68%;">
				{% if doc.get("reference") %}
				<div class="line"><strong>{{ _("Reference :") }}</strong>&ensp;{{ doc.get("reference") }}</div>
				{% endif %}
			</td>
			<td style="width: 32%;">
				{% set salutation = frappe.db.get_value("Customer", doc.customer, "salutation") %}
				{% if salutation %}<div>{{ _(salutation) }}</div>{% endif %}
				<div>{{ doc.customer_name }}</div>
				{% if doc.customer_address %}
					{% set ca = frappe.db.get_value("Address", doc.customer_address,
						["address_line1", "address_line2", "pincode", "city", "country"], as_dict=True) %}
					<div>
						{{ ca.address_line1 or "" }}<br>
						{% if ca.address_line2 %}{{ ca.address_line2 }}<br>{% endif %}
						{{ ca.pincode or "" }} {{ ca.city or "" }}
						{% if ca.country and ca.country != "Switzerland" %}<br>{{ ca.country }}{% endif %}
					</div>
				{% else %}
					<div style="color: #c00;">{{ _("Customer address missing, please add to sales invoice") }}</div>
				{% endif %}
			</td>
		</tr>
	</table>

	{% if doc.get("subject") %}
	<div class="line" style="margin-top: 15px;"><strong>{{ _("Concerne :") }}</strong>&ensp;{{ doc.get("subject") }}</div>
	{% endif %}

	<table class="items">
		{{ items_header(show_discount) }}
		{%- for row in doc.items -%}
			{% if row.page_break %}
	</table>
	<div class="page-break"></div>
	<table class="items">
		{{ items_header(show_discount) }}
			{% endif %}
		<tr>
			<td>{{ row.description or "" }}</td>
			<td>{{ row.uom or "" }}</td>
			<td class="text-right">{{ row.get_formatted("qty") }}</td>
			<td class="text-right">{{ chf(row.rate) }}</td>
			{% if show_discount %}
			<td class="text-right">{% if row.discount_percentage %}{{ row.discount_percentage }}%{% endif %}</td>
			{% endif %}
			<td class="text-right">{{ chf(row.amount) }}</td>
		</tr>
		{%- endfor -%}
	</table>

	<table class="totals">
		<tr>
			<td class="text-right">{{ _("Sub-Total") }}</td>
			<td class="text-right">{{ chf(doc.total) }}</td>
		</tr>
		{%- if doc.discount_amount -%}
		<tr>
			<td class="text-right">{{ _("Discount") }}</td>
			<td class="text-right">{{ chf(doc.discount_amount) }}</td>
		</tr>
		<tr>
			<td class="text-right">{{ _("Net Total") }}</td>
			<td class="text-right">{{ chf(doc.net_total) }}</td>
		</tr>
		{%- endif -%}
		{%- for tax in doc.taxes -%}
			{%- if tax.tax_amount_after_discount_amount -%}
		<tr>
			<td class="text-right">{{ tax.description }}</td>
			<td class="text-right">{{ chf(tax.tax_amount_after_discount_amount) }}</td>
		</tr>
			{%- endif -%}
		{%- endfor -%}
		<tr class="grand">
			<td class="text-right">{{ _("Total") }} {{ doc.currency }}</td>
			<td class="text-right">{{ chf(total_due) }}</td>
		</tr>
	</table>

	{% if doc.terms %}
	<div class="terms">{{ doc.terms }}</div>
	{% endif %}

</div>
